mapper.update:
UPDATE swm_safety_person_training
progress=#{progress}, complete_date=#{completeDate}, complete_status=#{completeStatus}, update_date=now()
WHERE id = #{id}

mapper.select:
SELECT fm.title, fm.push_date, fm.job_type, fm.type, sp.name as personName, jso.office_name AS "company", pa.position_name AS "department", pl.prod_line_name AS "prodLine", wg.work_group_name AS "team", a.* FROM swm_safety_person_training a JOIN swm_safety_file_manage fm ON a.safety_manage_id = fm.id JOIN swm_person sp ON a.identity_card = sp.identity_card LEFT JOIN fms_position_archive pa ON sp.department = pa.id COLLATE utf8mb4_general_ci LEFT JOIN fms_prod_line pl ON sp.prod_line = pl.id COLLATE utf8mb4_general_ci LEFT JOIN fms_work_group wg ON sp.team = wg.id COLLATE utf8mb4_general_ci LEFT JOIN js_sys_office jso ON sp.company = jso.office_code COLLATE utf8mb4_general_ci
${sqlMap.where.toSql()}
AND sp.name LIKE concat('%',#{personName},'%')
AND fm.push_date = #{pushDateStr}
AND fm.title LIKE concat('%',#{title},'%')
AND pa.position_name = #{department}
AND pl.prod_line_name = #{prodLine}
AND wg.work_group_name = #{team}
AND jso.office_name LIKE CONCAT('%', #{company}, '%')
ORDER BY ${sqlMap.order.toSql()}

SELECT fm.title, fm.push_date, fm.job_type, fm.type, fm.cover_url, fm.file_url, fm.duration, sp.name AS personName, a.* FROM swm_safety_person_training a INNER JOIN swm_safety_file_manage fm ON a.safety_manage_id = fm.id INNER JOIN swm_person sp ON a.identity_card = sp.identity_card
AND a.complete_status = #{completeStatus}
AND (a.phone_number = #{phoneNumber} OR a.phone_number = #{phone})
AND a.phone_number = #{phoneNumber}
AND a.id = #{id}
ORDER BY ${sqlMap.order.toSql()}
